/* Direct browser integrations. Tokens stay in sessionStorage, never in exports. */
(function(root){
'use strict';
function category(label){var s=String(label).toLocaleLowerCase('fr');if(/surgel/.test(s))return 'Surgelés';if(/(tomate|carotte|courge|oignon|échalote|ail\b|épinard|salade|citron|pomme\b|banane|concombre|poivron|champignon|chou|basilic|persil|sauge)/.test(s))return 'Fruits & légumes';if(/(lait|œuf|oeuf|yaourt|fromage|parmesan|feta|ricotta|mozzarella|crème|beurre|poulet)/.test(s))return 'Frais';if(/(surgel|petits pois|fève)/.test(s))return 'Surgelés';if(/(pain|tartine|baguette)/.test(s))return 'Boulangerie';return 'Épicerie';}
function normalize(s){return String(s).trim().toLocaleLowerCase('fr').replace(/\s+/g,' ');}
async function request(fetcher,url,options,service){var controller=new AbortController(),timeout=setTimeout(function(){controller.abort();},15000);try{var r=await fetcher(url,Object.assign({},options,{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'}));if(!r.ok){var e=new Error(r.status===401?service+' : connexion expirée.':r.status===403?service+' : accès refusé. Vérifie les autorisations du compte.':r.status===429?service+' : limite atteinte. Patiente avant de réessayer.':r.status===404&&service==='Spotify'?'Ouvre Spotify sur un appareil et lance un morceau.':service+' : requête refusée ('+r.status+').');e.status=r.status;if(r.status===429)e.retryAfter=Math.max(60000,(Number(r.headers&&r.headers.get('Retry-After'))||60)*1000);throw e;}if(r.status===204)return null;var text=await r.text();return text?JSON.parse(text):null;}catch(e){if(e.name==='AbortError')throw new Error(service+' met trop de temps à répondre. Actualise avant de réessayer une écriture.');if(e instanceof TypeError)throw new Error(service+' est inaccessible. Vérifie Internet puis actualise.');throw e;}finally{clearTimeout(timeout);}}
function todoist(token,fetcher){fetcher=fetcher||fetch;if(!token||/\s/.test(token))throw new Error('Indique un jeton Todoist valide.');function call(path,body){return request(fetcher,'https://api.todoist.com/api/v1'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)},'Todoist');}async function pages(path,key){var items=[],cursor='',seen=new Set();for(var n=0;n<20;n++){var data=await call(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+encodeURIComponent(cursor):''));if(!data||!Array.isArray(data[key||'results']))throw new Error('Réponse Todoist inattendue.');items=items.concat(data[key||'results']);cursor=data.next_cursor;if(!cursor)return items;if(seen.has(cursor))throw new Error('Pagination Todoist interrompue.');seen.add(cursor);}throw new Error('Liste Todoist trop longue. Affine le projet.');}return {projects:function(){return pages('/projects');},createProject:function(){return call('/projects',{name:'Courses'});},sections:function(project){return pages('/sections?project_id='+encodeURIComponent(project));},createSection:function(project,name){return call('/sections',{project_id:project,name:name});},tasks:function(project){return pages('/tasks?project_id='+encodeURIComponent(project));},completed:function(project,now){var end=new Date(now||Date.now()),start=new Date(end.getTime()-7*86400000);return pages('/tasks/completed/by_completion_date?project_id='+encodeURIComponent(project)+'&since='+encodeURIComponent(start.toISOString())+'&until='+encodeURIComponent(end.toISOString()),'items');},add:function(project,label,section,description){var body={project_id:project,content:label,description:description||''};if(section)body.section_id=section;return call('/tasks',body);},update:function(id,body){return call('/tasks/'+encodeURIComponent(id),body);},move:function(id,project,section){return call('/tasks/'+encodeURIComponent(id)+'/move',section?{section_id:section}:{project_id:project});},toggle:function(id,done){return call('/tasks/'+encodeURIComponent(id)+(done?'/close':'/reopen'),{});}};}
function base64(bytes){return btoa(String.fromCharCode.apply(null,bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function random(){return base64(crypto.getRandomValues(new Uint8Array(48)));}
function spotify(options){var fetcher=options.fetch||fetch,storage=options.storage||{getItem:function(k){try{return root.sessionStorage.getItem(k);}catch(_){return null;}},setItem:function(k,v){try{root.sessionStorage.setItem(k,v);}catch(_){throw new Error('Le stockage de session est indisponible. Autorise-le pour connecter Spotify.');}},removeItem:function(k){try{root.sessionStorage.removeItem(k);}catch(_){}}},location=options.location||root.location,history=options.history||root.history,refreshing;
 function get(key){try{return JSON.parse(storage.getItem('hub.spotify.'+key));}catch(_){return null;}}
 function set(key,value){storage.setItem('hub.spotify.'+key,JSON.stringify(value));}
 function clear(){['token','pending'].forEach(function(k){storage.removeItem('hub.spotify.'+k);});}
 function redirect(){if(location.protocol!=='https:'&&!['127.0.0.1','[::1]'].includes(location.hostname))throw new Error('Connecte Spotify depuis le site HTTPS, ou utilise http://127.0.0.1:4173.');return location.origin+location.pathname;}
 async function tokenRequest(body){var data=await request(fetcher,'https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(body).toString()},'Spotify');if(!data||!data.access_token)throw new Error('Réponse Spotify inattendue.');var old=get('token');set('token',{access_token:data.access_token,refresh_token:data.refresh_token||old&&old.refresh_token,expires:Date.now()+data.expires_in*1000,client_id:body.client_id});return data.access_token;}
 async function access(){var t=get('token');if(!t)throw new Error('Connecte ton compte Spotify.');if(t.expires>Date.now()+60000)return t.access_token;if(!t.refresh_token){clear();throw new Error('Reconnecte ton compte Spotify.');}if(!refreshing)refreshing=tokenRequest({grant_type:'refresh_token',refresh_token:t.refresh_token,client_id:t.client_id}).catch(function(e){if(e.status===400||e.status===401)clear();throw e;}).finally(function(){refreshing=null;});return refreshing;}
 return {connected:function(){return !!get('token');},disconnect:clear,redirect:redirect,authorize:async function(client){if(!/^[a-f0-9]{32}$/i.test(client))throw new Error('Indique le Client ID de ton application Spotify.');var uri=redirect(),verifier=random(),state=random(),digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier));set('pending',{verifier:verifier,state:state,client:client,uri:uri,time:Date.now()});var params=new URLSearchParams({client_id:client,response_type:'code',redirect_uri:uri,scope:'user-read-playback-state user-modify-playback-state',state:state,code_challenge_method:'S256',code_challenge:base64(new Uint8Array(digest))});location.assign('https://accounts.spotify.com/authorize?'+params);},callback:async function(){var p=new URLSearchParams(location.search);if(!p.has('state')||(!p.has('code')&&!p.has('error')))return false;var pending=get('pending');history.replaceState({},'',location.pathname);storage.removeItem('hub.spotify.pending');if(!pending||pending.state!==p.get('state')||Date.now()-pending.time>600000)throw new Error('Connexion Spotify expirée ou invalide. Recommence depuis Hub.');if(p.has('error'))throw new Error('Connexion Spotify annulée.');await tokenRequest({grant_type:'authorization_code',code:p.get('code'),redirect_uri:pending.uri,client_id:pending.client,code_verifier:pending.verifier});return true;},player:async function(){return request(fetcher,'https://api.spotify.com/v1/me/player',{headers:{Authorization:'Bearer '+await access()}},'Spotify');},control:async function(command){var methods={play:'PUT',pause:'PUT',next:'POST',previous:'POST'};if(!methods[command])throw new Error('Commande inconnue.');return request(fetcher,'https://api.spotify.com/v1/me/player/'+command,{method:methods[command],headers:{Authorization:'Bearer '+await access()}},'Spotify');}};
}
var api={category:category,normalize:normalize,todoist:todoist,spotify:spotify};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.HubConnect=api;
}(typeof window==='undefined'?this:window));
